enum Size { S, M, L }
class Main {
  public static void main(String[] args) {
    Size s = Size.M;
    switch (s) {
      case S: System.out.println("small"); break;
      case M: System.out.println("medium"); break;
      default: System.out.println("other");
    }
  }
}

